# Specs

This is a directory for test plans.
import { test } from "../fixtures/test.ts";

/**
 * Seed for Playwright's test agents (`npx playwright init-agents`). It uses the suite's own
 * fixture, so the agents start from a restored database and a signed-in admin session, and
 * opens the dashboard.
 */
test("seed", async ({ page }) => {
  await page.goto("/");
});
import { e2eConfig } from "../../config.ts";
import { expect, test } from "../../fixtures/test.ts";
import { OrderPage } from "../../pages/orderPage.ts";
import { findOrderId, ORDERS_SCENARIO } from "../../scenarios/orders.ts";

/**
 * What happens to an order after it is placed. Replaces legacy SALEOR_77 and 80 (paid,
 * fulfilled, tracked - one lifecycle), SALEOR_78 (partial manual captures) and SALEOR_81
 * and 82 (address edits either side of fulfillment). SALEOR_79, the same lifecycle on the
 * deprecated payment (`Payment` object) flow, is deliberately not ported.
 */
test.use({ scenario: ORDERS_SCENARIO });

const config = e2eConfig();

test("Mark as paid, fulfill and add tracking #e2e", async ({ page }) => {
  // Arrange
  const orderPage = new OrderPage(page);

  await orderPage.goto(await findOrderId(config, "unpaid"));

  // Act & Assert
  await test.step("mark as paid", async () => {
    await orderPage.markAsPaid("e2e-reference");
    await expect(orderPage.paymentStatusBadges).toContainText("Fully charged");
    await expect(orderPage.transactions).toContainText("Mark-as-paid transaction");
  });

  await test.step("fulfill", async () => {
    await orderPage.fulfillAll();
    await expect(orderPage.statusInfo).toHaveText("Fulfilled");
  });

  await test.step("add tracking", async () => {
    await orderPage.addTracking("TRACK-123");
    await expect(orderPage.trackingNumber).toContainText("TRACK-123");
  });
});

test("Manual captures charge an order in parts #e2e", async ({ page }) => {
  // Arrange
  const orderPage = new OrderPage(page);

  await orderPage.goto(await findOrderId(config, "unpaid"));

  // Read rather than computed: the scenario's shipping method has a seeded, random price.
  const total = await orderPage.readTotal();
  const firstPart = 1;

  // Act & Assert
  await test.step("a capture below the total leaves the order partly charged", async () => {
    await orderPage.captureManually({ description: "first part", amount: firstPart });
    await expect(orderPage.paymentStatusBadges).toContainText("Not fully charged");
    await expect(orderPage.statusInfo).toHaveText("Unfulfilled");
  });

  await test.step("capturing the rest charges it fully", async () => {
    await orderPage.captureManually({ description: "second part", amount: total - firstPart });
    await expect(orderPage.paymentStatusBadges).toContainText("Fully charged");
    await expect(orderPage.transactions.getByText("Manual capture")).toHaveCount(2);
  });
});

test("Addresses stay editable before and after fulfillment #e2e", async ({ page }) => {
  // Arrange
  const orderPage = new OrderPage(page);
  const change = { firstName: "Grace", streetAddress1: "1 Main Street" };

  // Act & Assert
  await test.step("shipping address of an unfulfilled order", async () => {
    await orderPage.goto(await findOrderId(config, "unpaid"));
    await orderPage.editShippingAddressButton.click();
    await orderPage.addressDialog.changeAddress(change);
    await expect(orderPage.shippingAddressSection).toContainText(change.streetAddress1);
    await expect(orderPage.billingAddressSection).not.toContainText(change.streetAddress1);
  });

  await test.step("billing address of a fulfilled order", async () => {
    await orderPage.goto(await findOrderId(config, "fulfilled"));
    await expect(orderPage.statusInfo).toHaveText("Fulfilled");
    await orderPage.editBillingAddressButton.click();
    await orderPage.addressDialog.changeAddress(change);
    await expect(orderPage.billingAddressSection).toContainText(change.streetAddress1);
    await expect(orderPage.shippingAddressSection).not.toContainText(change.streetAddress1);
  });
});
import { type Page } from "@playwright/test";

import { AddressDialog } from "./addressDialog.ts";

/**
 * A placed order: payment, fulfillment, tracking and addresses. Ported from the legacy
 * `OrdersPage` and its dialogs; the locators carry over, except that tracking now lives in
 * the timeline view of the order's lines, which is not the default.
 */
export class OrderPage {
  readonly addressDialog = new AddressDialog(this.page);

  readonly dialog = this.page.getByRole("dialog");

  readonly statusInfo = this.page.getByTestId("status-info");

  readonly markAsPaidButton = this.page.getByTestId("mark-as-paid-button");

  readonly transactionReferenceInput = this.page.getByTestId("transaction-reference-input");

  readonly paymentStatusBadges = this.page.getByTestId("payment-status-badges");

  readonly transactions = this.page.getByTestId("orderTransactionsList");

  readonly manualTransactionButton = this.page.getByTestId("captureManualTransactionButton");

  readonly transactionDescriptionInput = this.page.getByTestId("transactionDescription");

  readonly transactionAmountInput = this.page.getByTestId("transactAmountInput");

  readonly manualTransactionSubmit = this.page.getByTestId("manualTransactionSubmit");

  readonly fulfillButton = this.page.getByTestId("order-items-fulfill-button");

  readonly confirmFulfillmentButton = this.page.getByTestId("button-bar-confirm");

  readonly timelineView = this.page.getByTestId("order-items-view-timeline");

  readonly addTrackingButton = this.page.getByTestId("add-tracking-button");

  readonly trackingNumberInput = this.page.getByTestId("tracking-number-input");

  readonly confirmTrackingButton = this.page.getByTestId("confirm-tracking-number-button");

  readonly trackingNumber = this.page.getByTestId("tracking-number-set");

  readonly total = this.page.getByTestId("order-total");

  readonly shippingAddressSection = this.page.getByTestId("shipping-address-section");

  readonly billingAddressSection = this.page.getByTestId("billing-address-section");

  readonly editShippingAddressButton = this.page.getByTestId("edit-shipping-address");

  readonly editBillingAddressButton = this.page.getByTestId("edit-billing-address");

  constructor(readonly page: Page) {}

  async goto(orderId: string) {
    await this.page.goto(`/orders/${orderId}`);
    await this.statusInfo.waitFor();
  }

  async markAsPaid(reference: string) {
    await this.markAsPaidButton.click();
    await this.transactionReferenceInput.fill(reference);
    await this.dialog.getByTestId("submit").click();
    await this.dialog.waitFor({ state: "hidden" });
  }

  async captureManually({ description, amount }: { description: string; amount: number }) {
    await this.manualTransactionButton.click();
    await this.transactionDescriptionInput.fill(description);
    await this.transactionAmountInput.fill(amount.toFixed(2));
    await this.manualTransactionSubmit.click();
    await this.dialog.waitFor({ state: "hidden" });
  }

  /** Fulfills every line from the warehouses the fulfillment page proposes. */
  async fulfillAll() {
    await this.fulfillButton.click();
    await this.page.waitForURL(url => url.pathname.endsWith("/fulfill"));
    await this.confirmFulfillmentButton.click();
    await this.page.waitForURL(url => !url.pathname.endsWith("/fulfill"));
  }

  async addTracking(trackingNumber: string) {
    await this.timelineView.click();
    await this.addTrackingButton.click();
    await this.trackingNumberInput.fill(trackingNumber);
    await this.confirmTrackingButton.click();
    await this.dialog.waitFor({ state: "hidden" });
  }

  /** The order total as a number - it is rendered without its currency. */
  async readTotal(): Promise<number> {
    return Number((await this.total.innerText()).trim());
  }
}
import type { E2eConfig } from "../config.ts";
import { adminToken, assertNoMutationErrors, gql } from "../lib/graphql.ts";
import { step } from "../lib/progress.ts";
import type { Scenario } from "./scenario.ts";

/**
 * The default scenario plus the order states the order specs start from.
 *
 * `populatedb` alone cannot serve them: its orders are random (channel, customer, a 10%
 * chance of being unconfirmed, fulfilled whenever they happen to be paid) and its catalogue
 * promotions hit random products. So this scenario brings its own products at known prices,
 * one known customer, one promotion of each kind, and orders a spec can look up by name -
 * see `findOrderId`. Everything lives in one channel.
 *
 * `populatedb`'s own promotions are deleted, so no price here depends on which products
 * its random draw picked.
 */
export const ORDERS_SCENARIO = "orders";

/** Marks orders as paid with a transaction - `populatedb`'s default. */
export const CHANNEL = { slug: "default-channel", name: "Channel-USD" } as const;

export const CUSTOMER = {
  email: "e2e.customer@example.com",
  firstName: "Ada",
  lastName: "Lovelace",
};

const CUSTOMER_ADDRESS = {
  firstName: CUSTOMER.firstName,
  lastName: CUSTOMER.lastName,
  streetAddress1: "69 W 9th Street",
  city: "New York",
  postalCode: "10001",
  country: "US",
  countryArea: "NY",
  phone: "+12125771133",
};

/** Prices in the channel's currency, USD. */
export const PRODUCTS = {
  /** Discounted by the catalogue promotion. */
  tee: { name: "E2E Tee", sku: "e2e-tee", price: 10 },
  hoodie: { name: "E2E Hoodie", sku: "e2e-hoodie", price: 50 },
} as const;

export const PROMOTIONS = {
  catalogue: { name: "E2E Tee sale", percent: 20 },
  order: { name: "E2E big basket", percent: 10, subtotalAtLeast: 30 },
} as const;

/**
 * Orders, keyed by what a spec needs from them. Each carries its key as `e2e` metadata,
 * which is how `findOrderId` finds it - ids differ per build of the dump.
 */
export const SCENARIO_ORDERS = {
  /** One tee, unpaid and unfulfilled. */
  unpaid: { paid: false },
  /** One tee, paid and fulfilled. */
  fulfilled: { paid: true },
} as const;

export type ScenarioOrder = keyof typeof SCENARIO_ORDERS;

type Mutate = <T extends Record<string, unknown>>(
  name: string,
  query: string,
  variables?: Record<string, unknown>,
) => Promise<T>;

