259	const createOrder = async (
260	  mutate: Mutate,
261	  {
262	    ref,
263	    channelId,
264	    customerId,
265	    variantId,
266	    warehouseId,
267	    paid,
268	  }: {
269	    ref: ScenarioOrder;
270	    channelId: string;
271	    customerId: string;
272	    variantId: string;
273	    warehouseId: string;
274	    paid: boolean;
275	  },
276	) => {
277	  const { order: draft } = await mutate<{
278	    order: { id: string; shippingMethods: { id: string }[] };
279	  }>(
280	    "draftOrderCreate",
281	    `mutation($input: DraftOrderCreateInput!) {
282	      draftOrderCreate(input: $input) {
283	        order { id shippingMethods { id } }
284	        errors { field code message }
285	      }
286	    }`,
287	    {
288	      input: {
289	        channelId,
290	        user: customerId,
291	        lines: [{ variantId, quantity: 1 }],
292	        shippingAddress: CUSTOMER_ADDRESS,
293	        billingAddress: CUSTOMER_ADDRESS,
294	        metadata: [{ key: "e2e", value: ref }],
295	      },
296	    },
297	  );
298	
299	  await mutate(
300	    "draftOrderUpdate",
301	    `mutation($id: ID!, $input: DraftOrderInput!) {
302	      draftOrderUpdate(id: $id, input: $input) { errors { field code message } }
303	    }`,
304	    { id: draft.id, input: { shippingMethod: draft.shippingMethods[0].id } },
305	  );
306	
307	  const { order } = await mutate<{ order: { id: string; lines: { id: string }[] } }>(
308	    "draftOrderComplete",
309	    `mutation($id: ID!) {
310	      draftOrderComplete(id: $id) { order { id lines { id } } errors { field code message } }
311	    }`,
312	    { id: draft.id },
313	  );
314	
315	  if (!paid) {
316	    return;
317	  }
318	
319	  await mutate(
320	    "orderMarkAsPaid",
321	    `mutation($id: ID!) { orderMarkAsPaid(id: $id) { errors { field code message } } }`,
322	    { id: order.id },
323	  );
324	  await mutate(
325	    "orderFulfill",
326	    `mutation($order: ID!, $input: OrderFulfillInput!) {
327	      orderFulfill(order: $order, input: $input) { errors { field code message } }
328	    }`,
329	    {
330	      order: order.id,
331	      input: {
332	        notifyCustomer: false,
333	        lines: order.lines.map(line => ({
334	          orderLineId: line.id,
335	          stocks: [{ warehouse: warehouseId, quantity: 1 }],
336	        })),
337	      },
338	    },
339	  );
340	};
341	
342	export const ordersScenario: Scenario = {
343	  name: ORDERS_SCENARIO,
344	  parent: "default",
345	  build: async (config, getAdminToken) => {
346	    const token = await getAdminToken();
347	    const mutate = mutator(config, token);
348	    const shop = await lookUpShop(config, token);
349	
350	    const variantIds = await step("creating products", () => createProducts(mutate, shop));
351	    const teeProductId = (
352	      await gql<{ productVariant: { product: { id: string } } }>(
353	        config,
354	        `query($id: ID!) { productVariant(id: $id) { product { id } } }`,
355	        { id: variantIds.tee },
356	        token,
357	      )
358	    ).productVariant.product.id;
359	
360	    await step("replacing the promotions", () => createPromotions(mutate, shop, teeProductId));
361	
362	    const { user } = await mutate<{ user: { id: string } }>(
363	      "customerCreate",
364	      `mutation($input: UserCreateInput!) {
365	        customerCreate(input: $input) { user { id } errors { field code message } }
366	      }`,
367	      {
368	        input: {
369	          ...CUSTOMER,
370	          defaultShippingAddress: CUSTOMER_ADDRESS,
371	          defaultBillingAddress: CUSTOMER_ADDRESS,
372	        },
373	      },
374	    );
375	
376	    await step("creating orders", async () => {
377	      for (const [ref, { paid }] of Object.entries(SCENARIO_ORDERS)) {
378	        await createOrder(mutate, {
379	          ref: ref as ScenarioOrder,
380	          channelId: shop.channelId,
381	          customerId: user.id,
382	          variantId: variantIds.tee,
383	          warehouseId: shop.warehouseId,
384	          paid,
385	        });
386	      }
387	    });
388	  },
389	};
390	
391	/**
392	 * The id of one of `SCENARIO_ORDERS` in the restored database. A read, so it is safe at
393	 * test time; ids are not constants because every build of the dump mints new ones.
394	 */
395	export const findOrderId = async (config: E2eConfig, ref: ScenarioOrder): Promise<string> => {
396	  const data = await gql<{ orders: { edges: { node: { id: string } }[] } }>(
397	    config,
398	    `query($ref: String!) {
399	      orders(first: 1, filter: { metadata: [{ key: "e2e", value: $ref }] }) { edges { node { id } } }
400	    }`,
401	    { ref },
402	    await adminToken(config),
403	  );
404	  const [order] = data.orders.edges;
405	
406	  if (!order) {
407	    throw new Error(`the "${ORDERS_SCENARIO}" scenario has no order "${ref}"`);
408	  }
409	
410	  return order.node.id;
411	};
